import java.util.*;
class Boundaries {static class Request{String route;int id,stage;Request(String route,int id){this.route=route;this.id=id;}}record Result(List<Integer> completed,List<Integer> failed,List<Integer> pending,int overhead){}static Result simulate(List<String> routes,boolean services,int capacity,int ticks,boolean paymentDown,int hopCost){List<Request>pending=new ArrayList<>();for(int i=0;i<routes.size();i++)pending.add(new Request(routes.get(i),i));List<Integer>completed=new ArrayList<>(),failed=new ArrayList<>();int overhead=0;
for(int tick=0;tick<ticks;tick++){if(!services){int budget=capacity;for(int i=0;i<pending.size()&&budget>0;){Request r=pending.get(i);int work=r.route.equals("catalog")?1:3;if(paymentDown){failed.add(r.id);pending.remove(i);continue;}if(work>budget){i++;continue;}budget-=work;completed.add(r.id);pending.remove(i);}}
else{int[] budgets={Math.max(1,capacity/3),capacity/3,capacity-Math.max(1,capacity/3)-capacity/3};for(int stage=2;stage>=0;stage--)for(int i=0;i<pending.size()&&budgets[stage]>0;){Request r=pending.get(i);if(r.stage!=stage){i++;continue;}budgets[stage]--;if(stage>0)overhead+=hopCost;if(stage==2&&paymentDown){failed.add(r.id);pending.remove(i);}else if(r.route.equals("catalog")||stage==2){completed.add(r.id);pending.remove(i);}else{r.stage++;i++;}}}}
List<Integer>remaining=new ArrayList<>();for(Request r:pending)remaining.add(r.id);
return new Result(completed,failed,remaining,overhead);}}
